//! 🔐️ Public shared-slot relocation and exact original replacement refusal.

 use super::*;use crate::native_decoding::{NativeConstructionRecipientIssuer,NativeDecodeConstructionRecipient,NativeDecodeWorkIssuer,NativeDecodeWorkRecipient};
 struct Construction;impl NativeDecodeConstructionRecipient for Construction{fn submitted(&self)->RetainedCloneProgress{Default::default()}fn grant(&mut self,d:RetirementDemand)->Result<RetainedCloneGrant,ValueError>{Ok(RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth})}fn accept(&mut self,grant:RetainedCloneGrant,progress:RetainedCloneProgress)->Result<(),ValueError>{assert!(progress.fits(grant));Ok(())}}
 struct Work;impl NativeDecodeWorkRecipient for Work{fn available_work(&mut self,observed:u64)->Result<u64,ValueError>{1_000_000u64.checked_sub(observed).ok_or_else(||ValueError::invariant("observed test work exceeds its finite scope"))}fn admits(&mut self,observed:u64,additional:u64)->Result<bool,ValueError>{Ok(additional<=self.available_work(observed)?)}}
 fn close<T:RetireOwned>(value:T){let law:serde_json::Value=serde_json::from_str(include_str!("../../🧪️tests/🧫️fixtures/📐️.json")).unwrap();let mut bank=crate::source_fixture::Wallet::from_profile(&law["stock"]);let mut owner=crate::retirement::controlled::ControlledRetirement::new(value).unwrap_or_else(|_|panic!("original owner requires paid close"));let mut actual=None;for _ in 0..10000{if owner.terminal_is_empty()&&actual.is_none(){return}let grant=bank.loan(1,4096);let(turn,heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||crate::source_fixture::close_step(&mut actual,grant,bank.work_remaining(),owner.next_demand(4096),owner.next_computational_work(4096),|g,a|{let result=owner.step(g,a);crate::RetainedWorkOutcome{result,work:owner.last_turn_work()}}));let p=turn.result.as_ref().map(|step|step.progress()).unwrap_or_else(|e|e.retained_progress());bank.post(p,turn.work,grant,heap);turn.result.unwrap();}panic!("original owner did not close")}
 /// 🔐️ Relocation retains the captured original payload and rejects replacement.
 #[test]fn native_shared_slots_keep_original_across_relocation_and_reject_replacement(){let fixture:serde_json::Value=serde_json::from_str(include_str!("../../../🏭️construction/🧪️tests/🧫️fixtures/effect-frame.json")).unwrap();let mut original=Some(fixture["slotCustody"][0]["owner"].as_str().unwrap().to_owned());let pointer=original.as_ref().unwrap().as_ptr();let mut replacement=Some(fixture["slotCustody"][1]["candidate"].as_str().unwrap().to_owned());let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:4096,maximum_capacity_bytes:4096,maximum_release_bytes:4096,maximum_depth:8};let mut slots=NativeSharedSlots::<String,SealedShared<String>>::default();assert!(slots.capture(&mut original,grant).result.is_ok());assert!(slots.capture(&mut replacement,grant).result.is_err());assert!(replacement.is_some());let mut slots=Box::new(slots);assert_eq!(slots.input().unwrap().as_ptr(),pointer);let mut callback=|_|true;let mut control=NativeDecodeControl::new(4096,&mut callback);let mut recipient=Construction;let mut issuer=NativeConstructionRecipientIssuer::new();let mut work=Work;let mut work_issuer=NativeDecodeWorkIssuer::new();for _ in 0..2{let mut loan=issuer.loan(&mut recipient);let mut work_loan=work_issuer.loan(&mut work);let turn=control.with_work_recipient(&mut work_loan,|control|control.with_construction_recipient(&mut loan,|control|Ok::<_,ValueError>(slots.advance(control,SharedIssuer::owned())))).unwrap();assert!(turn.result.is_ok())}assert!(slots.output_ready());let mut output=None;assert!(slots.take(&mut output,grant).result.is_ok());assert!(slots.terminal_is_empty());assert_eq!(output.as_ref().unwrap().get().as_ptr(),pointer);close(output.take().unwrap());close(replacement.take().unwrap());}
